package in.ac.rtu.medicare.web;
import in.ac.rtu.medicare.model.User; import in.ac.rtu.medicare.service.AuthService; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.IOException;
@WebServlet({"/login","/register","/logout"}) public class AuthServlet extends HttpServlet {private final AuthService auth=new AuthService();protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException {if(r.getServletPath().equals("/logout")){HttpSession s=r.getSession(false);if(s!=null)s.invalidate();p.sendRedirect(r.getContextPath()+"/login");return;}r.getRequestDispatcher("/WEB-INF/views/"+(r.getServletPath().equals("/register")?"register.jsp":"login.jsp")).forward(r,p);}protected void doPost(HttpServletRequest r,HttpServletResponse p)throws IOException,ServletException {try {if(r.getServletPath().equals("/register")){auth.register(r.getParameter("name"),r.getParameter("email"),r.getParameter("password").toCharArray(),r.getParameter("phone"));p.sendRedirect(r.getContextPath()+"/login?registered=1");return;}User u=auth.login(r.getParameter("email"),r.getParameter("password").toCharArray());HttpSession old=r.getSession(false);if(old!=null)old.invalidate();HttpSession s=r.getSession(true);s.setAttribute("user",u);s.setMaxInactiveInterval(20*60);p.sendRedirect(r.getContextPath()+"/app/dashboard");}catch(Exception e){r.setAttribute("error",e.getMessage());doGet(r,p);}}}
